// ---- invites

// CreateInvite invites an email address to join an organization with a role. It returns the invite with its token, which
// the caller must send to the invited address: the store keeps only the token's hash. An earlier pending invite to the
// same address (ignoring case) is revoked, so only the newest token works.
func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
	email = strings.TrimSpace(email)
	if !validEmail(email) {
		return Invite{}, invalid("an invite needs a valid email address")
	}
	if !role.Valid() || role == RoleOwner {
		return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Invite{}, ErrNotFound
	}
	if uid, ok := s.usersByEmail[normEmail(email)]; ok {
		if _, member := s.members[memberKey{orgID, uid}]; member {
			return Invite{}, ErrAlreadyMember
		}
	}
	for id, old := range s.invites {
		if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && isPending(old, now) {
			t := now.UTC()
			old.RevokedAt = &t
			s.invites[id] = old
		}
	}
	token := newInviteToken()
	stored := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: HashToken(token), InvitedBy: invitedBy, CreatedAt: now.UTC()}
	s.invites[stored.ID] = stored
	inv := stored
	inv.Token = token
	return inv, nil
}

// isPending reports whether an invite can still be accepted at now.
func isPending(inv Invite, now time.Time) bool {
	return inv.AcceptedAt == nil && inv.RevokedAt == nil && !now.After(inv.ExpiresAt())
}

// Invite returns one of an organization's invites.
func (s *Store) Invite(orgID, id string) (Invite, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, false
	}
	return inv, true
}

// Invites returns an organization's invites that were neither accepted nor revoked, oldest first. It includes expired
// invites; PendingInvites leaves them out.
func (s *Store) Invites(orgID string) []Invite {
	return s.orgInvites(orgID, func(inv Invite) bool { return inv.AcceptedAt == nil && inv.RevokedAt == nil })
}

// PendingInvites returns an organization's invites that can still be accepted at now, oldest first.
func (s *Store) PendingInvites(orgID string, now time.Time) []Invite {
	return s.orgInvites(orgID, func(inv Invite) bool { return isPending(inv, now) })
}

// orgInvites returns an organization's invites that keep, oldest first. The caller does not hold the lock.
func (s *Store) orgInvites(orgID string, keep func(Invite) bool) []Invite {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invite{}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && keep(inv) {
			out = append(out, inv)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// RevokeInvite withdraws an invite.
func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, ErrNotFound
	}
	if inv.RevokedAt == nil {
		t := now.UTC()
		inv.RevokedAt = &t
		s.invites[id] = inv
	}
	return inv, nil
}

// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
// makes them a member with the invite's role and gives them a first API key. An unknown or revoked token is ErrNotFound,
// an accepted one ErrInviteUsed and one older than InviteLifetime ErrInviteExpired.
func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, found := s.inviteByToken(token)
	if !found || inv.RevokedAt != nil {
		return User{}, Member{}, APIKey{}, ErrNotFound
	}
	if inv.AcceptedAt != nil {
		return User{}, Member{}, APIKey{}, ErrInviteUsed
	}
	if now.After(inv.ExpiresAt()) {
		return User{}, Member{}, APIKey{}, ErrInviteExpired
	}
	var u User
	if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
		u = s.users[id]
	} else {
		name = strings.TrimSpace(name)
		if name == "" {
			return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
		}
		u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
	if err != nil {
		return User{}, Member{}, APIKey{}, err
	}
	k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
	if err != nil {
		return User{}, Member{}, APIKey{}, err
	}
	t := now.UTC()
	inv.AcceptedAt = &t
	s.invites[inv.ID] = inv
	return u, m, k, nil
}

// inviteByToken finds the invite a token belongs to. The caller holds the lock.
func (s *Store) inviteByToken(token string) (Invite, bool) {
	if token == "" {
		return Invite{}, false
	}
	h := HashToken(token)
	for _, inv := range s.invites {
		if inv.TokenHash == h {
			return inv, true
		}
	}
	return Invite{}, false
}
