// InviteLifetime is how long an invite can be accepted after it is created.
const InviteLifetime = 7 * 24 * time.Hour

// Invite asks someone to join an organization. Its token is sent to the invited address and never stored: the store keeps
// only the token's hash (TokenHash).
type Invite struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Email string `json:"email"`
	Role  Role   `json:"role"`
	// Token is the secret. It is set only on the invite CreateInvite returns, so the caller can email it; it is not
	// stored or serialized.
	Token      string     `json:"-"`
	TokenHash  string     `json:"token_hash"`
	InvitedBy  string     `json:"invited_by"`
	CreatedAt  time.Time  `json:"created_at"`
	AcceptedAt *time.Time `json:"accepted_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// ExpiresAt is when the invite stops being accepted: InviteLifetime after it was created.
func (inv Invite) ExpiresAt() time.Time { return inv.CreatedAt.Add(InviteLifetime) }

