	first := emailedToken(t, e)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "NEW@people.example", "role": "viewer"}, nil)
	second := emailedToken(t, e)
	if first == second {
		t.Fatal("the new invite has the old token")
	}
	if r := e.Do("POST", "/v1/invites/accept", "", acceptBody(first)); r.Code != http.StatusNotFound {
		t.Fatalf("the superseded token: %s", r)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", acceptBody(second), nil)
	var me struct{ Role string }
	var keyOf struct {
		APIKey store.APIKey `json:"api_key"`
	}
	_ = keyOf
	e.MustDo(http.StatusOK, "GET", "/v1/members", e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/me", e.Acme.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("owner: %s", r)
	}
	_ = me
}
